export type HandcraftedThemeId = (typeof HANDCRAFTED_THEME_IDS)[number];
export type CentralGlyphId = (typeof CENTRAL_GLYPH_IDS)[number];
export type CentralPatternId = (typeof CENTRAL_PATTERN_IDS)[number];
export type EmblemColourRole = "primary" | "secondary" | "accent";

export type CentralGlyphPiece = Readonly<{
  glyph: CentralGlyphId;
  role: EmblemColourRole;
  x: number;
  y: number;
  scale: number;
  rotate: number;
  mirror: boolean;
}>;

export type CentralGeometry = Readonly<{
  x: number;
  y: number;
  scaleX: number;
  scaleY: number;
  rotate: number;
  patternRotate: number;
  patternScale: number;
  patternDensity: number;
  patternPhase: number;
}>;

type EmblemPalette = Readonly<{
  primary: string;
  secondary: string;
  accent: string;
  ink: string;
}>;

export type HandcraftedThemeEmblemSpec = EmblemPalette & Readonly<{
  themeId: HandcraftedThemeId;
  name: string;
  family: "handcrafted";
  motif: HandcraftedThemeId;
  signature: string;
  visualSignature: string;
}>;

export type OriginalThemeEmblemDescriptor = EmblemPalette & Readonly<{
  themeId: ThemeId;
  catalogNumber: number;
  name: string;
  family: "future";
  /** Human-authored concept label. It is never parsed from the saved ID. */
  motif: string;
  keywords: readonly [string, string, string];
  /** Human-authored name for the complete central outline. */
  silhouette: string;
  pattern: CentralPatternId;
  pieces: readonly [CentralGlyphPiece, CentralGlyphPiece, ...CentralGlyphPiece[]];
  geometry: CentralGeometry;
  signature: string;
  /** Explicit geometry identity; palette is deliberately excluded. */
  visualSignature: string;
}>;

export type ThemeEmblemSpec = HandcraftedThemeEmblemSpec | OriginalThemeEmblemDescriptor;

