type OriginalInput = Omit<OriginalThemeEmblemDescriptor, "family">;

function original(input: OriginalInput): OriginalThemeEmblemDescriptor {
  const pieces = Object.freeze(input.pieces.map((piece) => Object.freeze(piece))) as unknown as OriginalThemeEmblemDescriptor["pieces"];
  return Object.freeze({
    ...input,
    family: "future" as const,
    keywords: Object.freeze([...input.keywords]) as OriginalThemeEmblemDescriptor["keywords"],
    pieces,
    geometry: Object.freeze({ ...input.geometry }),
  });
}

